// SPDX-License-Identifier: AGPL-3.0-or-later  ·  Copyright (c) 2026 John Chen
// ROOF PRESETS by building type. roofs.mjs merges these into ROOF_PRESETS (applyPresets): the old presets switch to texture
// palettes (roof-texture.mjs), and a preset per building type is added so a builder never invents a roof from scratch:
//
//   cottage  shop  townhouse  civic  temple  granary  modern     (the originals, now palettes)
//   barn            gambrel along the long axis, barn-red, quartz barge, dormers both long sides, ridge cupola
//   teahouse/pagoda dutch gable, pitch 0.67, upturned eaves, dark-glazed tiles
//   tower-cap       cone 2.75:1 over a round or octagonal tower (wizard, keep)
//   lantern-cap     shallow cone (pitch 1.25: 0.75 read as a pancake) with a ring course and finial (lighthouse lantern room)
//   church/stave    three stacked, steeper roofs with wall bands between, dragon ridge ends
//   workshop        sawtooth with glazed vertical faces, copper
//   desert          flat sandstone deck, quartz coping, wind tower
//   cafe            flat cantilever deck, per-side overhang, quartz fascia, spruce soffit
//
// A preset is (P) => roof() options, P = { R, w, d, span, len, wide, front, frontZ, frontLen, side, wallH, y0 }.
// `steep: true` exempts the preset from the "no taller than the walls" pitch easing (it sets its own proportions).
const cx = (P) => Math.floor((P.R[0] + P.R[2]) / 2), cz = (P) => Math.floor((P.R[1] + P.R[3]) / 2);

/** Palettes for the old presets (material only: every other option is the original's). */
export const PALETTE_FOR = { cottage: "spruce-shingle", shop: "spruce-shingle", civic: "slate", townhouse: "dark-slate", granary: "slate", temple: "red-tile" };

export const NEW_PRESETS = {
  barn: (P) => ({
    style: "gambrel", ridgeAxis: P.wide ? "x" : "z", pitch: 1.5, upperPitch: 0.5, lower: Math.max(2, Math.round((0.4 * P.span) / 2)),
    material: "barn-red", verge: "smooth_quartz", ridge: "slab", overhang: 1, steep: true,
    dormers: { face: P.wide ? ["north", "south"] : ["east", "west"], count: P.len >= 18 ? 3 : 2, style: "gable" },
    tower: { at: [cx(P) - 1, cz(P) - 1], size: 3, height: 2, top: "lantern", material: "spruce" },
  }),
  teahouse: (P) => ({
    style: "dutch-gable", pitch: 0.67, eave: "upturned", ridge: "slab",
    material: { mix: [["deepslate_tile", 50], ["cobbled_deepslate", 30], ["polished_blackstone_brick", 20]], eave: "polished_blackstone_brick", ridge: "stone_brick", verge: "dark_oak" },   // dark-glazed with a stone-grey ridge (not quartz white) overhang: 1, steep: true,
    maxHeight: Math.max(2, Math.floor(0.6 * (P.wallH || 4))),
  }),
  "tower-cap": (P) => ({ style: "cone", pitch: 2.75, material: "slate", overhang: 1, steep: true, ...(P.span >= 7 ? { dormer: { face: P.front } } : {}) }),
  "lantern-cap": () => ({ style: "cone", pitch: 1.25, material: "red-tile", overhang: 1, ring: true, steep: true }),
  church: () => ({ style: "tiered", tiers: 3, material: { mix: [["dark_oak", 40], ["spruce", 30], ["mangrove", 15], ["cobbled_deepslate", 15]], eave: "dark_oak", ridge: "dark_oak", gradient: "none" }, pitches: [1, 1.5, 2], overhang: 1, ridgeEnds: "dragon", steep: true }),
  workshop: () => ({ style: "sawtooth", material: "copper", pitch: 1, glaze: "north", overhang: 0, steep: true }),
  desert: (P) => ({
    style: "flat-parapet", parapet: 1, material: { mix: [["smooth_sandstone", 60], ["sandstone", 25], ["mud_brick", 15]], eave: "smooth_quartz", ridge: "smooth_quartz", gradient: "none" }, trim: "smooth_quartz", overhang: 0, steep: true,
    tower: { at: [P.R[0] + 2, P.R[1] + 2], size: 3, height: 2, top: "cap", material: "smooth_sandstone", from: P.y0 + 1 },
  }),
  cafe: () => ({
    style: "flat-parapet", parapet: 0, cantilever: true, overhang: { north: 2, south: 1, east: 1, west: 1 },
    material: { mix: [["smooth_stone", 50], ["cobbled_deepslate", 25], ["polished_andesite", 25]], gradient: "none" }, trim: "smooth_quartz", fascia: "smooth_quartz", soffit: "spruce", steep: true,
  }),
};
NEW_PRESETS.pagoda = NEW_PRESETS.teahouse;
NEW_PRESETS.stave = NEW_PRESETS.church;

/** Mutate the roofs.mjs preset table: old presets get palettes, new presets are added (an old name is never replaced). */
export function applyPresets(table) {
  for (const [name, palette] of Object.entries(PALETTE_FOR)) {
    const orig = table[name];
    if (orig) table[name] = (P) => ({ ...orig(P), material: palette });
  }
  for (const [name, fn] of Object.entries(NEW_PRESETS)) if (!table[name]) table[name] = fn;
  return table;
}
