  { name: "camelback front", footprint: [15, 9, 20, 12], style: "gable", o: { y: 7, pitch: 1, ridgeAxis: "z", front: "north", material: "stone", ridge: "stone_slab", verge: "stripped_pale_oak_log", overhang: { north: 1, south: 0, east: 1, west: 1 } } },
  // plot 1 camel hump: 2 storeys, gable over the rear rooms; north gable triangle stays wall (keep)
  { name: "camel hump", footprint: [15, 13, 20, 17], style: "gable", o: { y: 12, pitch: 1, ridgeAxis: "z", material: "stone", ridge: "stone_slab", verge: "stripped_pale_oak_log", overhang: { north: 0, south: 1, east: 1, west: 1 }, keep: [{ from: [15, 12, 13], to: [20, 14, 13] }, { from: [13, 7, 14], to: [14, 20, 15] }] } },
  // plot 2 I-house: side gable, dark slate, quartz verge; end chimneys kept
  { name: "I-house", footprint: [25, 9, 34, 16], style: "gable", o: { y: 12, pitch: 1, ridgeAxis: "x", material: "dark-slate", ridge: "slab", verge: "smooth_quartz", overhang: { north: 1, south: 1, east: 0, west: 0 }, keep: [{ from: [25, 6, 12], to: [25, 20, 12] }, { from: [34, 6, 12], to: [34, 20, 12] }] } },
  // plot 3 pyramid cottage: true pyramid, polished granite, stack kept through the apex
  { name: "pyramid", footprint: [37, 9, 46, 17], style: "pyramid", o: { y: 7, pitch: 1, material: "polished_granite", ridge: "slab", overhang: 1, keep: [{ from: [41, 6, 12], to: [42, 15, 13] }] } },
  // plot 4 boarding house: side gable, tuff brick, polished tuff eave; kitchen chimney kept
  { name: "boarding house", footprint: [49, 9, 58, 16], style: "gable", o: { y: 12, pitch: 1, ridgeAxis: "x", material: "tuff_brick", eave: "polished_tuff", ridge: "slab", verge: "stripped_oak_log", overhang: { north: 1, south: 1, east: 0, west: 0 }, keep: [{ from: [49, 6, 12], to: [50, 20, 13] }] } },
  // plot 5 smokehouse: small steep front gable, blackstone; vent shaft kept at z 17
  { name: "smokehouse", footprint: [61, 12, 65, 16], style: "gable", o: { y: 5, pitch: 1.5, ridgeAxis: "z", material: "blackstone", ridge: "slab", verge: "spruce", overhang: { north: 1, south: 1, east: 1, west: 0 }, keep: [{ from: [63, 5, 17], to: [63, 15, 17] }] } },
  // plot 7 bungalow: low front gable over porch and body, green copper mix; brick chimney kept
  { name: "bungalow", footprint: [85, 7, 94, 17], style: "gable", o: { y: 7, pitch: 0.5, ridgeAxis: "z", front: "north", material: { mix: [["oxidized_cut_copper", 70], ["weathered_cut_copper", 30]] }, ridge: "slab", verge: "smooth_quartz", overhang: { north: 1, south: 1, east: 0, west: 0 }, keep: [{ from: [85, 6, 13], to: [86, 20, 14] }] } },
];

// hand porch roofs: a shed of stairs on the front line (high side toward the house) and a slab row behind
const PORCHES = [
  // [x0, x1, z, roofY, stairs material, slab material, slab type]
  { name: "dogtrot porch", x0: 1, x1: 10, z: 7, y: 6, stairs: "exposed_cut_copper", slab: "exposed_cut_copper" },
  { name: "camelback porch", x0: 15, x1: 20, z: 7, y: 6, stairs: "stone", slab: "stone_slab" },
  { name: "I-house gallery", x0: 25, x1: 34, z: 7, y: 11, stairs: "deepslate_tile", slab: "deepslate_tile_slab", slabType: "top" },
  { name: "pyramid porch", x0: 37, x1: 46, z: 7, y: 6, stairs: "polished_granite", slab: "polished_granite_slab" },
  { name: "boarding porch", x0: 49, x1: 58, z: 7, y: 6, stairs: "tuff_brick", slab: "tuff_brick_slab" },
];

export function build(g) {
  for (const r of ROOFS) {
    const res = roof(g, r.footprint, r.style, { ...r.o, _notes: undefined });
    if (res.refused) console.log(`roofs: ${r.name} kept ${res.refused} cells`);
  }
  for (const p of PORCHES) {
    for (let x = p.x0; x <= p.x1; x++) {
      if (g.isAir(x, p.y, p.z)) g.set(x, p.y, p.z, ...B.stairs(p.stairs, "south", "bottom"));
      if (g.isAir(x, p.y + 1, p.z + 1)) g.set(x, p.y + 1, p.z + 1, ...B.slab(p.slab, p.slabType ?? "bottom"));
    }
  }
  // the smokehouse lean-to: a flat spruce slab roof on its posts, x 67..70 z 14..17, y 4
  for (let x = 67; x <= 70; x++) for (let z = 14; z <= 17; z++) if (g.isAir(x, 4, z)) g.set(x, 4, z, ...B.slab("spruce", "bottom"));
}

